#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Issue 20: benchmark the local LLM candidates on the M4 Max, one model at a time
# (the disk is nearly full), and post the results on the spec issue.
REPO="addeelnayyer/meeting-copilot"
SPEC_ISSUE=14
TASK_ISSUE=20
# Smallest first; the largest needs the most free disk, so it runs last.
MODELS=(granite4:7b-a1b-h qwen3.5:4b qwen3.5:9b gemma4:26b qwen3.5:35b-a3b)
LARGE=" qwen3.5:9b gemma4:26b qwen3.5:35b-a3b "   # large-machine candidates
DEFAULT_MODEL="granite4:7b-a1b-h"                  # shipped default, kept installed
DEFAULT_ALT="qwen3.5:4b"                           # challenger on the German lines
SUGG_P95_MAX=3000; TRANSLIT_P95_MAX=1500           # pass bar, ms
RESULTS="sessions/llm-bench"                       # git-ignored
# The same settings for every model, whatever .env says.
BENCH_ENV=(LANGUAGES=en,ur PROMPT=system)

_slug() { printf '%s' "$1" | tr ':/' '__'; }
_out() { printf '%s/%s.txt' "$RESULTS" "$(_slug "$1")"; }
_ran() { [[ -s "$(_out "$1")" ]] && grep -q '^=====' "$(_out "$1")"; }
_ollama_url() { local u; u=$(_existing OLLAMA_URL || true); printf '%s' "${u:-http://127.0.0.1:11434}"; }
_installed() { ollama list 2>/dev/null | awk -v m="$1" 'NR>1 && ($1==m || $1==m":latest"){f=1} END{exit !f}'; }
_free_gb() { df -k "${OLLAMA_MODELS:-$HOME/.ollama}" 2>/dev/null | awk 'NR==2{printf "%.1f", $4/1e6}'; }

# _download_gb MODEL: total layer size in the Ollama registry, or "?".
_download_gb() {
  local name="${1%%:*}" tag="${1#*:}"
  [[ "$1" == *:* ]] || tag="latest"
  [[ "$name" == */* ]] || name="library/$name"
  curl -fsS -H 'Accept: application/vnd.docker.distribution.manifest.v2+json' \
    "https://registry.ollama.ai/v2/$name/manifests/$tag" 2>/dev/null \
    | uv run --quiet python -c 'import json,sys; print(round(sum(l["size"] for l in json.load(sys.stdin)["layers"])/1e9, 1))' 2>/dev/null \
    || printf '?'
}

# _row FILE KIND -> "n p50 p95 valid errors" from the bench summary table.
_row() {
  awk -v k="$2" '
    /^=====/ {s=1; next}
    s && /^$/ {exit}
    s && $2==k {
      if (k=="suggestion" || k=="german") {v=$6; e=$7} else {v="-"; e=$6}
      print $3, $4, $5, v, (e=="" ? 0 : e)
    }' "$1"
}

# _samples FILE KIND prints that call type's sample blocks.
_samples() { awk -v k="$2" '/^--- /{p = (index($0, "--- " k " sample") == 1)} p' "$1"; }

# _side_by_side KIND FILE_A FILE_B: each sample of a call type, with both runs' outputs under it
# (the bench prints the models of one run side by side, and each model is its own run here).
_side_by_side() {
  awk -v k="$1" '
    FNR==1 {fi++; n=0; p=0}
    /^--- / {p = (index($0, "--- " k " sample") == 1); if (p) {n++; if (fi==1) H[n]=$0}; next}
    p && NF {L[fi, n] = L[fi, n] $0 "\n"; if (n > N) N = n}
    END {for (i = 1; i <= N; i++) printf "%s\n%s%s\n", H[i], L[1, i], L[2, i]}' "$2" "$3"
}

_le() { awk -v a="$1" -v b="$2" 'BEGIN{exit !(a != "-" && a+0 <= b+0)}'; }
_all_valid() { [[ "$1" == */* && "${1%/*}" == "${1#*/}" && "${1#*/}" != 0 ]]; }

# _fails MODEL prints why it misses the pass bar (empty: it passes).
_fails() {
  local f; f=$(_out "$1")
  _ran "$1" || { printf 'not benchmarked'; return; }
  local why=() n p50 p95 v e
  read -r n p50 p95 v e <<<"$(_row "$f" suggestion)"
  _all_valid "$v" || why+=("suggestion JSON $v")
  _le "$p95" "$SUGG_P95_MAX" || why+=("suggestion p95 ${p95} ms")
  read -r n p50 p95 v e <<<"$(_row "$f" german)"
  _all_valid "$v" || why+=("german JSON $v")
  read -r n p50 p95 v e <<<"$(_row "$f" transliteration)"
  _le "$p95" "$TRANSLIT_P95_MAX" || why+=("transliteration p95 ${p95} ms")
  [[ "$(head -n1 "$RESULTS/$(_slug "$1").urdu" 2>/dev/null)" == yes ]] || why+=("Roman Urdu not judged readable")
  (( ${#why[@]} )) && { local IFS=';'; printf '%s' "${why[*]}" | sed 's/;/; /g'; }
  return 0
}

# bench_model MODEL KEEP: pull if needed, benchmark warm, record sizes, remove unless KEEP=1.
bench_model() {
  local m="$1" keep="$2" out need free
  out=$(_out "$m")
  if _ran "$m"; then
    say "An earlier run of $m is saved in $out."
    if confirm "Reuse it (n runs the benchmark again)?"; then pause; return 0; fi
  fi
  if ! _installed "$m"; then
    need=$(_download_gb "$m")
    while :; do
      free=$(_free_gb)
      say "Download: ${need} GB. Free disk: ${free} GB."
      if [[ "$need" == "?" ]] || awk -v n="$need" -v f="$free" 'BEGIN{exit !(f >= n + 1)}'; then break; fi
      warn "Not enough space: $m needs ${need} GB plus 1 GB headroom."
      step "Free space (empty the Trash, clear ~/Library/Caches, remove other Ollama models with: ollama rm <name>)."
      note "$DEFAULT_MODEL is 4.2 GB; you can remove it now and pull it again after this model."
      confirm "Re-check the free space (n skips $m)?" || { SKIPPED+=("benchmark $m (not enough disk)"); pause; return 0; }
    done
    ollama pull "$m" || { warn "Pull failed."; SKIPPED+=("benchmark $m (pull failed)"); pause; return 0; }
  fi
  say "Benchmarking $m warm (it warms up first, then about a minute or more of calls)."
  if ! env "${BENCH_ENV[@]}" uv run python -m copilot.llm_bench "$m" 2>&1 | tee "$out"; then
    warn "The benchmark failed (output above, saved in $out)."
    SKIPPED+=("benchmark $m (run failed, see $out)")
  fi
  # Sizes: on disk (ollama list) and loaded in memory (ollama ps), while the model is still loaded.
  { ollama list | awk -v m="$m" 'NR>1 && $1==m {print "disk " $3 " " $4}'
    ollama ps   | awk -v m="$m" 'NR>1 && $1==m {print "loaded " $3 " " $4}'
  } > "$RESULTS/$(_slug "$m").size"
  ollama stop "$m" >/dev/null 2>&1 || true
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$m" "$RESET"
  sed 's/^/  /' "$RESULTS/$(_slug "$m").size"
  _ran "$m" && sed -n '/^=====/,/^$/p' "$out"
  if [[ "$keep" == 1 ]]; then
    note "$m is the shipped default, so it stays installed."
  elif confirm "Remove $m to free the disk for the next model?"; then
    ollama rm "$m"
  else
    SKIPPED+=("ollama rm $m")
  fi
  pause
}

# judge_urdu MODEL: the native reader's verdict on its Roman Urdu, saved as yes|no + note.
judge_urdu() {
  local m="$1" vf; vf="$RESULTS/$(_slug "$m").urdu"
  _clear
  printf '\n%s%s  Roman Urdu: %s%s\n\n' "$BOLD" "$BLUE" "$m" "$RESET"
  _samples "$(_out "$m")" transliteration
  printf '\n'
  if [[ -s "$vf" ]]; then
    note "Saved verdict: $(head -n1 "$vf") ($(sed -n 2p "$vf"))"
    confirm "Keep it?" && return 0
  fi
  local verdict=no
  confirm "Does the native reader judge this Roman Urdu readable?" && verdict=yes
  ask URDU_NOTE "One line on why (spelling, script, missed words):"
  printf '%s\n%s\n' "$verdict" "$URDU_NOTE" > "$vf"
  URDU_NOTE=""
}

_cell() {   # "p50 / p95" of a call type
  local n p50 p95 v e; read -r n p50 p95 v e <<<"$(_row "$1" "$2")"
  printf '%s / %s' "$p50" "$p95"
}

write_comment() {
  local m f n p50 p95 v e vs vg errs size fails urdu
  {
    printf '## Local LLM benchmark results (#%s)\n\n' "$TASK_ISSUE"
    printf '%s. Machine: %s, %s GB. Warm models, one at a time, `python -m copilot.llm_bench` at %s.\n\n' \
      "$(date +%Y-%m-%d)" "$MACHINE" "$MEM_GB" "$(git rev-parse --short HEAD)"
    printf '`%s`\n\n' "$(grep -m1 '^Ollama ' "$(_out "$DEFAULT_MODEL")" 2>/dev/null || echo "Ollama $OLLAMA_VERSION")"
    printf 'Pass bar: valid JSON on every suggestion call, suggestion p95 <= %s ms, transliteration p95 <= %s ms, Roman Urdu judged readable by a native reader.\n\n' \
      "$SUGG_P95_MAX" "$TRANSLIT_P95_MAX"
    printf '| Model | Disk | Loaded | Suggestion p50/p95 ms | Translation | Transliteration | German | Valid JSON (sugg., German) | Errors | Pass |\n'
    printf '|---|---|---|---|---|---|---|---|---|---|\n'
    for m in "${MODELS[@]}"; do
      f=$(_out "$m")
      if ! _ran "$m"; then printf '| `%s` | | | not run | | | | | | |\n' "$m"; continue; fi
      size="$RESULTS/$(_slug "$m").size"
      read -r n p50 p95 vs e <<<"$(_row "$f" suggestion)"
      read -r n p50 p95 vg e <<<"$(_row "$f" german)"
      errs=$(for k in suggestion translation transliteration german; do _row "$f" "$k"; done | awk '{s+=$5} END{print s+0}')
      fails=$(_fails "$m")
      printf '| `%s` | %s | %s | %s | %s | %s | %s | %s, %s | %s | %s |\n' "$m" \
        "$(awk '$1=="disk"{print $2" "$3}' "$size" 2>/dev/null)" \
        "$(awk '$1=="loaded"{print $2" "$3}' "$size" 2>/dev/null)" \
        "$(_cell "$f" suggestion)" "$(_cell "$f" translation)" "$(_cell "$f" transliteration)" "$(_cell "$f" german)" \
        "$vs" "$vg" "$errs" "${fails:-yes}"
    done
    printf '\nFailures: '
    local any=0
    for m in "${MODELS[@]}"; do
      fails=$(_fails "$m"); [[ -n "$fails" && "$fails" != "not benchmarked" ]] && { printf '\n- `%s`: %s' "$m" "$fails"; any=1; }
    done
    (( any )) || printf 'none'
    printf '\n\n### Roman Urdu (native reader)\n\n'
    for m in "${MODELS[@]}"; do
      urdu="$RESULTS/$(_slug "$m").urdu"
      [[ -s "$urdu" ]] && printf -- '- `%s`: %s. %s\n' "$m" "$(head -n1 "$urdu" | sed 's/yes/readable/;s/no/not readable/')" "$(sed -n 2p "$urdu")"
    done
    printf '\n### German: `%s` against `%s`\n\n%s\n' "$DEFAULT_ALT" "$DEFAULT_MODEL" "$GERMAN_VERDICT"
    printf '\n### Decision\n\n'
    printf -- '- **Large-machine recommendation:** %s. %s\n' "$REC_LARGE" "$REC_LARGE_WHY"
    printf -- '- **Shipped default:** %s. %s\n' "$REC_DEFAULT" "$REC_DEFAULT_WHY"
    for m in "${MODELS[@]}"; do
      _ran "$m" || continue
      printf '\n<details><summary><code>%s</code>: summary and samples</summary>\n\n```\n' "$m"
      sed -n '/^=====/,$p' "$(_out "$m")"
      printf '```\n</details>\n'
    done
  } > "$RESULTS/comment.md"
}

run_wizard() {

TOTAL_STAGES=10
cd "$(dirname "$0")/.."
mkdir -p "$RESULTS"

banner "Local LLM benchmark (issue $TASK_ISSUE)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Update the checkout"
say "The benchmark (copilot/llm_bench.py) is on origin/main."
git fetch -q origin
behind=$(git rev-list --count HEAD..origin/main)
if (( behind > 0 )); then
  say "This checkout is $behind commit(s) behind origin/main."
  git status --short | sed 's/^/  /'
  if confirm "Fast-forward main to origin/main (local edits are kept)?"; then git pull --ff-only origin main
  else warn "Without it the benchmark may be missing."; fi
fi
[[ -f copilot/llm_bench.py ]] || { warn "copilot/llm_bench.py is missing; update the checkout first."; exit 1; }
uv sync
pause "Checkout ready. Press Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Ollama and a quiet machine"
command -v ollama >/dev/null || { warn "Ollama is not installed: https://ollama.com/download"; exit 1; }
until curl -fs "$(_ollama_url)/api/tags" >/dev/null; do
  warn "Ollama isn't running at $(_ollama_url)."
  open -a Ollama >/dev/null 2>&1 || step "Run 'ollama serve' in another terminal."
  pause "Press Enter once it is running"
done
OLLAMA_VERSION=$(curl -fs "$(_ollama_url)/api/version" | sed -E 's/.*"version":"([^"]+)".*/\1/')
MACHINE=$(sysctl -n machdep.cpu.brand_string 2>/dev/null || uname -m)
MEM_GB=$(( $(sysctl -n hw.memsize 2>/dev/null || echo 0) / 1073741824 ))
say "Ollama $OLLAMA_VERSION on $MACHINE, $MEM_GB GB."
if [[ "$(printf '%s\n0.31.2\n' "$OLLAMA_VERSION" | sort -V | head -n1)" != 0.31.2 ]]; then
  warn "Before 0.31.2, Ollama could ignore the JSON schema with thinking off (ollama/ollama#14645). Update Ollama first."
fi
say "Latency only means something on a quiet machine:"
step "Quit Meeting Copilot, call apps and anything heavy (Xcode, Docker, big browser sessions)."
step "Plug in the power adapter and turn Low Power Mode off."
loaded=$(ollama ps | awk 'NR>1{print $1}')
if [[ -n "$loaded" ]]; then
  say "Models loaded right now: $loaded"
  confirm "Unload them?" && for m in $loaded; do ollama stop "$m"; done
fi
pause "Press Enter when the machine is quiet"

# ── 3-7 ───────────────────────────────────────────────────────────────────
for m in "${MODELS[@]}"; do
  stage "Benchmark $m"
  [[ "$m" == "$DEFAULT_MODEL" ]] && keep=1 || keep=0
  bench_model "$m" "$keep"
done

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Roman Urdu: native reader"
say "A native Urdu reader judges each model's transliterations, one model per screen."
say "Each sample shows the Urdu line, then that model's Roman Urdu."
pause "Press Enter when the reader is here"
for m in "${MODELS[@]}"; do _ran "$m" && judge_urdu "$m"; done

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "German: $DEFAULT_ALT against $DEFAULT_MODEL"
GERMAN_VERDICT="Not compared: one of the two runs is missing."
if _ran "$DEFAULT_MODEL" && _ran "$DEFAULT_ALT"; then
  say "The same German suggestion calls, both models. Is $DEFAULT_ALT clearly better?"
  printf '\n'
  _side_by_side german "$(_out "$DEFAULT_MODEL")" "$(_out "$DEFAULT_ALT")"
  printf '\n'
  better=no
  confirm "Is $DEFAULT_ALT clearly better at German than $DEFAULT_MODEL?" && better=yes
  ask GERMAN_NOTE "One line on why:"
  GERMAN_VERDICT="$DEFAULT_ALT clearly better: $better. $GERMAN_NOTE"
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Decide and post the results on #$SPEC_ISSUE"
best=""; best_p95=""
for m in "${MODELS[@]}"; do
  fails=$(_fails "$m")
  if [[ -z "$fails" ]]; then say "${GREEN}pass${RESET}  $m"; else say "fail  $m: $fails"; fi
  if [[ -z "$fails" && "$LARGE" == *" $m "* ]]; then
    read -r _ _ p95 _ _ <<<"$(_row "$(_out "$m")" suggestion)"
    if [[ -z "$best" ]] || _le "$p95" "$best_p95"; then best="$m"; best_p95="$p95"; fi
  fi
done
printf '\n'
if [[ -n "$best" ]]; then
  suggested="\`$best\`"; suggested_why="The fastest large-machine candidate that passes (suggestion p95 $best_p95 ms)."
else
  suggested="none"; suggested_why="No large-machine candidate passes the bar."
fi
say "Suggested large-machine recommendation: $suggested. $suggested_why"
ask REC_LARGE "Recommendation (Enter accepts the suggestion, or type a model tag):"
REC_LARGE=${REC_LARGE:-$suggested}
[[ "$REC_LARGE" == "$suggested" ]] && REC_LARGE_WHY=$suggested_why || { ask REC_LARGE_WHY "Why this one:"; REC_LARGE="\`${REC_LARGE//\`/}\`"; }
if [[ -z "$(_fails "$DEFAULT_ALT")" && "${better:-no}" == yes ]]; then
  REC_DEFAULT="change to \`$DEFAULT_ALT\`"; why="It passes the bar and is clearly better at German."
else
  REC_DEFAULT="keep \`$DEFAULT_MODEL\`"; why="\`$DEFAULT_ALT\` $( [[ -n "$(_fails "$DEFAULT_ALT")" ]] && echo "misses the bar ($(_fails "$DEFAULT_ALT"))" || echo "is not clearly better at German")."
fi
say "Shipped default: $REC_DEFAULT. $why"
ask REC_DEFAULT_WHY "Reason (Enter keeps the one above):"
REC_DEFAULT_WHY=${REC_DEFAULT_WHY:-$why}
write_comment
say "Draft: $RESULTS/comment.md ($(wc -c < "$RESULTS/comment.md" | tr -d ' ') characters; GitHub allows 65536)."
if confirm "Open it in ${VISUAL:-${EDITOR:-nano}} to review and edit?"; then "${VISUAL:-${EDITOR:-nano}}" "$RESULTS/comment.md"; fi
if confirm "Post it as a public comment on $REPO#$SPEC_ISSUE?"; then
  url=$(gh issue comment "$SPEC_ISSUE" --repo "$REPO" --body-file "$RESULTS/comment.md")
  say "Posted: $url"
  if confirm "Close #$TASK_ISSUE with a link to it?"; then
    gh issue close "$TASK_ISSUE" --repo "$REPO" --comment "Results and decision: $url"
  fi
else
  SKIPPED+=("post the comment: gh issue comment $SPEC_ISSUE --repo $REPO --body-file $RESULTS/comment.md")
fi
pause

finish
}

run_wizard "$@"; exit
